sys_script_include.script:
var CiscoSecureAccessGetToken = Class.create();
CiscoSecureAccessGetToken.prototype = {
	initialize: function () {
	},

	getLatestAccessToken: function () {
		var tokenGR = new GlideRecord("u_cisco_secure_access_token");
		tokenGR.orderByDesc("sys_created_on");
		tokenGR.setLimit(1);
		tokenGR.query();

		if (!tokenGR.next()) {
			gs.error("[GetCiscoSecureAccessToken] No access token found");
			return null;
		}

		var accessToken = tokenGR.getValue("u_access_token");
		if (!accessToken) {
			gs.error("[GetCiscoSecureAccessToken] Access token is empty");
			return null;
		}

		return accessToken;
	},

	type: 'CiscoSecureAccessGetToken'
};
